namespace ghidra.file.formats.ext4;



using ghidra.app.util.bin;
using ghidra.app.util.bin;
using ghidra.formats.gfilesystem;
using ghidra.formats.gfilesystem.factory;
using ghidra.formats.gfilesystem.factory;
using ghidra.util.exception;
using ghidra.util.task;

public class Ext4FileSystemFactory : GFileSystemProbeByteProvider, GFileSystemFactoryByteProvider<Ext4FileSystem> {

	/* @Override */
	public Ext4FileSystem create(FSRLRoot targetFSRL, ByteProvider byteProvider,
			FileSystemService fsService, TaskMonitor monitor)
    {

		try {
			Ext4FileSystem fs = new Ext4FileSystem(targetFSRL, byteProvider);
			fs.mountFS(monitor);

			return fs;
		}
		catch (IOException e) {
			FSUtilities.uncheckedClose(byteProvider, null);
			throw e;
		}
	}

	/* @Override */
	public bool probe(ByteProvider byteProvider, FileSystemService fsService,
			TaskMonitor taskMonitor)
    {
		try {
			BinaryReader reader = new BinaryReader(byteProvider, true);
			//ext4 has a 1024 byte padding at the beginning
			reader.setPointerIndex(Ext4Constants.SUPER_BLOCK_START);
			Ext4SuperBlock superBlock = new Ext4SuperBlock(reader);
			return superBlock.isValid();
		}
		catch (IOException e) {
			// ignore
		}
		return false;
	}
}
